public class CaseCommandTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected [" + expected + "] but got [" + actual + "]");
            failures++;
        }
    }

    static String capture(String[] argv) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            CaseCommand.main(argv);
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("upper hello world", "HELLO WORLD\n", capture(new String[]{"upper", "hello", "world"}));
        check("lower JAVA ROCKS", "java rocks\n", capture(new String[]{"lower", "JAVA", "ROCKS"}));
        check("upper single word", "ABC\n", capture(new String[]{"upper", "abc"}));
        check("lower OS X RULES", "os x rules\n", capture(new String[]{"lower", "OS", "X", "RULES"}));
        check("unknown command shout", "unknown command\n", capture(new String[]{"shout", "hello"}));
        check("unknown command empty string", "unknown command\n", capture(new String[]{"", "hello"}));
        check("upper with no words prints empty line", "\n", capture(new String[]{"upper"}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

